import { test, expect } from '@playwright/test';

test.describe('Task Deletion with Confirmation Dialog', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the task management application
    await page.goto('http://localhost:3000');

    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should display confirmation dialog when deleting a task', async ({ page }) => {
    // Create a task first
    const taskInput = page.getByLabel('Task input');
    await taskInput.fill('Test task to delete');

    const addButton = page.getByRole('button', { name: /add task/i });
    await addButton.click();

    // Wait for the task to appear
    const taskItem = page.getByText('Test task to delete');
    await taskItem.waitFor({ state: 'visible' });

    // Click delete button on the task
    const deleteButton = page.getByRole('button', { name: /delete/i }).first();
    await deleteButton.click();

    // Verify confirmation dialog appears
    const confirmDialog = page.getByRole('dialog');
    await expect(confirmDialog).toBeVisible();

    const confirmMessage = page.getByText(/are you sure you want to delete this task/i);
    await expect(confirmMessage).toBeVisible();
  });

  test('should delete task when confirming in the dialog', async ({ page }) => {
    // Create a task first
    const taskInput = page.getByLabel('Task input');
    await taskInput.fill('Task to be deleted');

    const addButton = page.getByRole('button', { name: /add task/i });
    await addButton.click();

    // Wait for the task to appear
    const taskItem = page.getByText('Task to be deleted');
    await taskItem.waitFor({ state: 'visible' });

    // Click delete button
    const deleteButton = page.getByRole('button', { name: /delete/i }).first();
    await deleteButton.click();

    // Confirm deletion
    const confirmButton = page.getByRole('button', { name: /confirm|yes|delete/i }).last();
    await confirmButton.click();

    // Verify task is deleted
    await expect(taskItem).not.toBeVisible();
  });

  test('should cancel deletion when clicking cancel button', async ({ page }) => {
    // Create a task first
    const taskInput = page.getByLabel('Task input');
    await taskInput.fill('Task to keep');

    const addButton = page.getByRole('button', { name: /add task/i });
    await addButton.click();

    // Wait for the task to appear
    const taskItem = page.getByText('Task to keep');
    await taskItem.waitFor({ state: 'visible' });

    // Click delete button
    const deleteButton = page.getByRole('button', { name: /delete/i }).first();
    await deleteButton.click();

    // Click cancel button
    const cancelButton = page.getByRole('button', { name: /cancel|no/i });
    await cancelButton.click();

    // Verify dialog is closed
    const confirmDialog = page.getByRole('dialog');
    await expect(confirmDialog).not.toBeVisible();

    // Verify task still exists
    await expect(taskItem).toBeVisible();
  });

  test('should close confirmation dialog when clicking outside of it', async ({ page }) => {
    // Create a task first
    const taskInput = page.getByLabel('Task input');
    await taskInput.fill('Another task');

    const addButton = page.getByRole('button', { name: /add task/i });
    await addButton.click();

    // Wait for the task to appear
    const taskItem = page.getByText('Another task');
    await taskItem.waitFor({ state: 'visible' });

    // Click delete button
    const deleteButton = page.getByRole('button', { name: /delete/i }).first();
    await deleteButton.click();

    // Click outside the dialog (on the backdrop)
    const backdrop = page.locator('[role="presentation"]');
    if (await backdrop.isVisible()) {
      await backdrop.click({ position: { x: 0, y: 0 } });
    }

    // Verify dialog is closed
    const confirmDialog = page.getByRole('dialog');
    await expect(confirmDialog).not.toBeVisible();

    // Verify task still exists
    await expect(taskItem).toBeVisible();
  });
});
